package net.civeira.phylax.features.document.templatevariable.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.templatevariable.domain.TemplateVariable;
import net.civeira.phylax.features.document.templatevariable.domain.valueobject.ValueVO;

@RequiredArgsConstructor
public class ValueValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ValueVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getValue() {
    return value.flatMap(ValueVO::getValue);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ValueVO> getValueValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ValueVO readValue(final Optional<TemplateVariable> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(TemplateVariable::getValueValue).orElseGet(ValueVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetValue() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetValueIfMatches(final String field) {
    if ("value".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param value
   * @return
   */
  public T value(ValueVO value) {
    this.value = Optional.of(value);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param value
   * @return
   */
  public T value(Optional<ValueVO> value) {
    this.value = value;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param value
   * @return
   */
  public T value(String value) {
    this.value = Optional.of(ValueVO.from(value));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T valueNull() {
    this.value = Optional.empty();
    return this.holder;
  }
}
